// MUTABLE ANTI-PATTERN: Dangerous shared state
class MutablePoint {
    public int x, y;
    public MutablePoint(int x, int y) { this.x = x; this.y = y; }
}

// IMMUTABLE PATTERN: Safe and reliable
final class ImmutablePoint {
    private final int x;
    private final int y;
    public ImmutablePoint(int x, int y) { this.x = x; this.y = y; }
    public int getX() { return x; }
    public int getY() { return y; }

    // Transformation returns a NEW instance
    public ImmutablePoint translate(int dx, int dy) {
        return new ImmutablePoint(this.x + dx, this.y + dy);
    }
}

public class ImmutabilityDemo {
    public static void main(String[] args) {
        // 1. Mutable bug: modifying p1 inadvertently corrupts p2
        MutablePoint mp1 = new MutablePoint(10, 20);
        MutablePoint mp2 = mp1; // Shared reference
        mp2.x = 999; // Corrupts mp1!
        System.out.println("Mutable mp1.x: " + mp1.x); // 999 (Bug!)

        // 2. Immutable safety: original never mutates
        ImmutablePoint ip1 = new ImmutablePoint(10, 20);
        ImmutablePoint ip2 = ip1.translate(5, 5);
        System.out.println("Immutable ip1.x: " + ip1.getX()); // Still 10!
        System.out.println("Immutable ip2.x: " + ip2.getX()); // 15
    }
}

