import java.math.BigDecimal;

public class StandardLibraryImmutabilityDemo {
    public static void main(String[] args) {
        // 1. String immutability
        String greeting = "Hello";
        greeting.concat(" World"); // Return value ignored!
        System.out.println("greeting after concat: " + greeting); // Still "Hello"!

        String fullGreeting = greeting.concat(" World");
        System.out.println("fullGreeting:           " + fullGreeting); // "Hello World"

        // 2. BigDecimal immutability
        BigDecimal price = new BigDecimal("19.99");
        BigDecimal tax = new BigDecimal("1.60");
        price.add(tax); // Does NOT mutate price!
        System.out.println("price after add:       $" + price); // Still $19.99!

        BigDecimal total = price.add(tax);
        System.out.println("total:                 $" + total); // $21.59
    }
}

