final class ComplexNumber {
    private final double real;
    private final double imag;

    public ComplexNumber(double real, double imag) {
        this.real = real;
        this.imag = imag;
    }
    public double getReal() { return real; }
    public double getImag() { return imag; }

    public ComplexNumber add(ComplexNumber other) {
        return new ComplexNumber(this.real + other.real, this.imag + other.imag);
    }
}

public class ComplexApp {
    public static void main(String[] args) {
        ComplexNumber c1 = new ComplexNumber(2.0, 3.0);
        ComplexNumber c2 = new ComplexNumber(4.0, 1.0);
        ComplexNumber c3 = c1.add(c2);

        System.out.println("c1: " + c1.getReal() + " + " + c1.getImag() + "i");
        System.out.println("c3: " + c3.getReal() + " + " + c3.getImag() + "i");
    }
}

final class Money {
    private final double amount;
    private final String currency;

    public Money(double amount, String currency) {
        if (amount < 0) {
            throw new IllegalArgumentException("Amount cannot be negative");
        }
        this.amount = amount;
        this.currency = currency;
    }
    public double getAmount() { return amount; }
    public String getCurrency() { return currency; }

    public Money convert(double exchangeRate, String newCurrency) {
        return new Money(this.amount * exchangeRate, newCurrency);
    }
}

public class CurrencyApp {
    public static void main(String[] args) {
        Money usd = new Money(100.0, "USD");
        Money eur = usd.convert(0.92, "EUR");

        System.out.println("USD: $" + usd.getAmount() + " " + usd.getCurrency());
        System.out.println("EUR: " + eur.getAmount() + " " + eur.getCurrency());
    }
}

final class ImmutableColor {
    private final int r, g, b;

    public ImmutableColor(int r, int g, int b) {
        if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255) {
            throw new IllegalArgumentException("Color components must be 0-255");
        }
        this.r = r;
        this.g = g;
        this.b = b;
    }

    public ImmutableColor blend(ImmutableColor other) {
        return new ImmutableColor(
            (this.r + other.r) / 2,
            (this.g + other.g) / 2,
            (this.b + other.b) / 2
        );
    }

    public String toHex() {
        return String.format("#%02X%02X%02X", r, g, b);
    }
}

public class ColorApp {
    public static void main(String[] args) {
        ImmutableColor red = new ImmutableColor(255, 0, 0);
        ImmutableColor blue = new ImmutableColor(0, 0, 255);
        ImmutableColor purple = red.blend(blue);

        System.out.println("Red: " + red.toHex());
        System.out.println("Blue: " + blue.toHex());
        System.out.println("Purple: " + purple.toHex());
    }
}

