final class ImmutableCounter {
    private final int count;
    public ImmutableCounter(int count) { this.count = count; }
    public int getCount() { return count; }

    public ImmutableCounter increment() {
        return new ImmutableCounter(this.count + 1);
    }
}

public class CounterBug {
    public static void main(String[] args) {
        ImmutableCounter c1 = new ImmutableCounter(0);
        ImmutableCounter c2 = c1.increment();
        System.out.println("c1: " + c1.getCount());
        System.out.println("c2: " + c2.getCount());
    }
}

final class SqlQuery {
    private final String selectClause;
    private final String fromClause;
    private final String whereClause;

    public SqlQuery(String selectClause, String fromClause, String whereClause) {
        this.selectClause = selectClause;
        this.fromClause = fromClause;
        this.whereClause = whereClause;
    }

    public static SqlQuery fromTable(String table) {
        return new SqlQuery("*", table, "");
    }

    public SqlQuery select(String columns) {
        return new SqlQuery(columns, this.fromClause, this.whereClause);
    }

    public SqlQuery where(String condition) {
        return new SqlQuery(this.selectClause, this.fromClause, condition);
    }

    public String build() {
        return "SELECT " + selectClause + " FROM " + fromClause +
            (whereClause.isEmpty() ? "" : " WHERE " + whereClause);
    }
}

public class QueryApp {
    public static void main(String[] args) {
        SqlQuery baseQuery = SqlQuery.fromTable("users");
        SqlQuery activeUsers = baseQuery.where("status = 'ACTIVE'");
        SqlQuery userEmails = activeUsers.select("id, email");

        System.out.println(baseQuery.build());
        System.out.println(activeUsers.build());
        System.out.println(userEmails.build());
    }
}
